// The vesting maths, exactly as the contract computes it
// (contracts/vesting/src/schedule.rs). The dApp uses it to preview a schedule
// before it is signed and to draw progress; the contract's views stay the
// authority for anything already on chain. Golden vectors generated by the Rust
// code check that the two agree (tests/schedule.test.ts).
//
// Amounts are bigint (token units); timestamps are numbers (seconds).

export const MAX_TRANCHES = 120;

export interface Tranche {
  time: number;
  amount: bigint;
}

export type Curve =
  | { kind: 'linear' }
  | { kind: 'stepped'; interval: number }
  | { kind: 'tranches'; tranches: Tranche[] };

export interface Schedule {
  start: number;
  cliff: number;
  cliffAmount: bigint;
  end: number;
  curve: Curve;
}

/** The contract's error messages (contracts/vesting/src/errors.rs). */
export const SCHEDULE_ERRORS = {
  zeroTotal: 'total must be more than zero',
  timeOrder: 'times must be start <= cliff <= end',
  cliffAboveTotal: 'cliff amount above total',
  zeroInterval: 'interval must be more than zero',
  intervalTooLong: 'interval longer than the schedule',
  trancheCount: 'tranche count out of range',
  zeroTranche: 'tranche amount must be more than zero',
  trancheBeforeStart: 'tranche before start',
  trancheOrder: 'tranche times must strictly increase',
  lastTrancheNotEnd: 'last tranche must be at the end',
  trancheSum: 'tranches plus cliff amount must equal the total'
} as const;

/** The contract's own check: null when valid, else the error it would return. */
export const validateSchedule = (
  schedule: Schedule,
  total: bigint
): string | null => {
  const { start, cliff, end, cliffAmount, curve } = schedule;
  if (total <= 0n) return SCHEDULE_ERRORS.zeroTotal;
  if (start > cliff || cliff > end) return SCHEDULE_ERRORS.timeOrder;
  if (cliffAmount > total) return SCHEDULE_ERRORS.cliffAboveTotal;
  switch (curve.kind) {
    case 'linear':
      return null;
    case 'stepped':
      if (curve.interval <= 0) return SCHEDULE_ERRORS.zeroInterval;
      if (curve.interval > end - start) return SCHEDULE_ERRORS.intervalTooLong;
      return null;
    case 'tranches': {
      const { tranches } = curve;
      if (tranches.length === 0 || tranches.length > MAX_TRANCHES) {
        return SCHEDULE_ERRORS.trancheCount;
      }
      let previous: number | undefined;
      let sum = 0n;
      for (const tranche of tranches) {
        if (tranche.amount <= 0n) return SCHEDULE_ERRORS.zeroTranche;
        if (tranche.time < start) return SCHEDULE_ERRORS.trancheBeforeStart;
        if (previous !== undefined && tranche.time <= previous) {
          return SCHEDULE_ERRORS.trancheOrder;
        }
        previous = tranche.time;
        sum += tranche.amount;
      }
      if (previous !== end) return SCHEDULE_ERRORS.lastTrancheNotEnd;
      if (sum + cliffAmount !== total) return SCHEDULE_ERRORS.trancheSum;
      return null;
    }
  }
};

const stepCount = (schedule: Schedule, interval: number) =>
  BigInt(Math.ceil((schedule.end - schedule.start) / interval));

/** What the curve has released of the rest at `t`, for cliff <= t < end. */
const restReleased = (schedule: Schedule, total: bigint, t: number): bigint => {
  const rest = total - schedule.cliffAmount;
  const { curve, start, end } = schedule;
  switch (curve.kind) {
    case 'linear':
      return (rest * BigInt(t - start)) / BigInt(end - start);
    case 'stepped': {
      const steps = stepCount(schedule, curve.interval);
      const done = BigInt(Math.floor((t - start) / curve.interval));
      return (rest * done) / steps;
    }
    case 'tranches': {
      let released = 0n;
      for (const tranche of curve.tranches) {
        if (tranche.time > t) break;
        released += tranche.amount;
      }
      return released;
    }
  }
};

/** The amount of `total` vested at second `t`. Assumes a valid schedule. */
export const vestedAt = (
  schedule: Schedule,
  total: bigint,
  t: number
): bigint => {
  if (t < schedule.cliff) return 0n;
  if (t >= schedule.end) return total;
  return schedule.cliffAmount + restReleased(schedule, total, t);
};

/** Vested at `t`, frozen at the cancel if there was one (0 = not cancelled). */
export const vestedWithCancel = (
  schedule: Schedule,
  total: bigint,
  cancelledAt: number,
  t: number
): bigint =>
  vestedAt(
    schedule,
    total,
    cancelledAt !== 0 && cancelledAt < t ? cancelledAt : t
  );

/** Smallest k with rest * k >= (released + 1) * span, i.e. the next growth. */
const nextGrowth = (rest: bigint, released: bigint, span: bigint) =>
  ((released + 1n) * span + rest - 1n) / rest;

const releaseAfter = (
  schedule: Schedule,
  total: bigint,
  t: number
): [number, bigint] | null => {
  if (t >= schedule.end) return null;
  const { curve, start, end } = schedule;
  let at: number;
  switch (curve.kind) {
    case 'linear': {
      const rest = total - schedule.cliffAmount;
      if (rest === 0n) return null;
      const duration = BigInt(end - start);
      const released = (rest * BigInt(t - start)) / duration;
      at = Math.min(start + Number(nextGrowth(rest, released, duration)), end);
      break;
    }
    case 'stepped': {
      const rest = total - schedule.cliffAmount;
      if (rest === 0n) return null;
      const steps = stepCount(schedule, curve.interval);
      const done = BigInt(Math.floor((t - start) / curve.interval));
      const released = (rest * done) / steps;
      const step = nextGrowth(rest, released, steps);
      at = Math.min(start + Number(step) * curve.interval, end);
      break;
    }
    case 'tranches':
      at = curve.tranches.find((tranche) => tranche.time > t)?.time ?? end;
      break;
  }
  return [at, vestedAt(schedule, total, at) - vestedAt(schedule, total, t)];
};

/**
 * The next moment after `now` when the vested amount grows, and by how much.
 * Null only when everything has vested.
 */
export const nextRelease = (
  schedule: Schedule,
  total: bigint,
  now: number
): [number, bigint] | null => {
  if (now >= schedule.end) return null;
  if (now < schedule.cliff) {
    const atCliff = vestedAt(schedule, total, schedule.cliff);
    if (atCliff > 0n) return [schedule.cliff, atCliff];
    return releaseAfter(schedule, total, schedule.cliff);
  }
  return releaseAfter(schedule, total, now);
};
